package main

import (
	"encoding/json"
	"log"
	"os"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// maxPollPerKey bounds how many messages a single poll returns for one key.
const maxPollPerKey = 1000

type request struct {
	Type    string           `json:"type"`
	MsgID   int              `json:"msg_id"`
	Key     string           `json:"key"`
	Msg     json.RawMessage  `json:"msg"`
	Offsets map[string]int64 `json:"offsets"`
	Keys    []string         `json:"keys"`
}

type pair [2]any

type pollOk struct {
	Type      string             `json:"type"`
	InReplyTo int                `json:"in_reply_to"`
	Msgs      map[string][]pair  `json:"msgs"`
}

type listOk struct {
	Type      string           `json:"type"`
	InReplyTo int              `json:"in_reply_to"`
	Offsets   map[string]int64 `json:"offsets"`
}

type sendOk struct {
	Type      string `json:"type"`
	InReplyTo int    `json:"in_reply_to"`
	Offset    int64  `json:"offset"`
}

type ok struct {
	Type      string `json:"type"`
	InReplyTo int    `json:"in_reply_to"`
}

type server struct {
	mu        sync.Mutex
	logs      map[string][]json.RawMessage
	committed map[string]int64

	// If true, list_committed_offsets reports the committed offset plus one
	// (i.e. the next offset to read), which matches Kafka's convention.
	commitNext bool
}

func (s *server) send(key string, msg json.RawMessage) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	l := s.logs[key]
	off := int64(len(l))
	s.logs[key] = append(l, msg)
	return off
}

func (s *server) poll(offsets map[string]int64) map[string][]pair {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string][]pair)
	for k, off := range offsets {
		l := s.logs[k]
		if off < 0 {
			off = 0
		}
		if off >= int64(len(l)) {
			continue
		}
		end := int64(len(l))
		if end-off > maxPollPerKey {
			end = off + maxPollPerKey
		}
		pairs := make([]pair, 0, end-off)
		for i := off; i < end; i++ {
			pairs = append(pairs, pair{i, l[i]})
		}
		out[k] = pairs
	}
	return out
}

func (s *server) commit(offsets map[string]int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for k, off := range offsets {
		if cur, ok := s.committed[k]; !ok || off > cur {
			s.committed[k] = off
		}
	}
}

func (s *server) listCommitted(keys []string) map[string]int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string]int64)
	for _, k := range keys {
		if off, ok := s.committed[k]; ok {
			if s.commitNext {
				off++
			}
			out[k] = off
		}
	}
	return out
}

func main() {
	log.SetOutput(os.Stderr)
	n := maelstrom.NewNode()
	s := &server{
		logs:      make(map[string][]json.RawMessage),
		committed: make(map[string]int64),
	}
	if mode := os.Getenv("KAFKA_COMMIT_MODE"); mode != "as-is" {
		s.commitNext = true
	}

	n.Handle("send", func(msg maelstrom.Message) error {
		var req request
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		off := s.send(req.Key, req.Msg)
		return n.Send(msg.Src, sendOk{Type: "send_ok", InReplyTo: req.MsgID, Offset: off})
	})

	n.Handle("poll", func(msg maelstrom.Message) error {
		var req request
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		msgs := s.poll(req.Offsets)
		return n.Send(msg.Src, pollOk{Type: "poll_ok", InReplyTo: req.MsgID, Msgs: msgs})
	})

	n.Handle("commit_offsets", func(msg maelstrom.Message) error {
		var req request
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		s.commit(req.Offsets)
		return n.Send(msg.Src, ok{Type: "commit_offsets_ok", InReplyTo: req.MsgID})
	})

	n.Handle("list_committed_offsets", func(msg maelstrom.Message) error {
		var req request
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		offsets := s.listCommitted(req.Keys)
		return n.Send(msg.Src, listOk{Type: "list_committed_offsets_ok", InReplyTo: req.MsgID, Offsets: offsets})
	})

	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

